
'use server';
/**
 * @fileOverview A Genkit flow for deleting a media asset from Firestore using the Admin SDK.
 */

import { ai } from '@/ai/genkit';
import { z } from 'genkit';
import * as admin from 'firebase-admin';

// This function initializes the Firebase Admin SDK.
// It checks if the app is already initialized to prevent errors in serverless environments.
function initializeAdminApp() {
  if (admin.apps.length === 0) {
    // In a managed environment like Cloud Functions or App Hosting,
    // initializeApp() with no arguments will use the environment's
    // service account credentials.
    admin.initializeApp();
  }
}

/**
 * A server-side function to delete a media asset document from Firestore.
 * This is a wrapper around the Genkit flow and is called by the client component.
 * @param mediaId The ID of the document to delete in the 'media' collection.
 * @returns A promise that resolves with an object indicating success or failure.
 */
export async function deleteMediaAsset(
  mediaId: string
): Promise<{ success: boolean; message: string }> {
  return await deleteMediaAssetFlow(mediaId);
}

/**
 * A Genkit flow that deletes a media asset document from Firestore using the Admin SDK.
 * This provides the necessary permissions to bypass client-side security rules.
 */
const deleteMediaAssetFlow = ai.defineFlow(
  {
    name: 'deleteMediaAssetFlow',
    inputSchema: z.string(), // The mediaId
    outputSchema: z.object({
      success: z.boolean(),
      message: z.string(),
    }),
  },
  async (mediaId) => {
    try {
      // Ensure the Admin SDK is initialized before use.
      initializeAdminApp();
      const db = admin.firestore();

      if (!mediaId) {
        return { success: false, message: 'Media ID is required.' };
      }

      const docRef = db.collection('media').doc(mediaId);
      await docRef.delete();

      console.log(`Successfully deleted media asset with ID: ${mediaId}`);
      return { success: true, message: 'Media asset deleted successfully.' };
    } catch (e: any) {
      console.error('Error in deleteMediaAssetFlow:', e);
      return {
        success: false,
        message: e.message || 'An unexpected server error occurred during deletion.',
      };
    }
  }
);
